-- Extensión necesaria para UUIDs si no está habilitada
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. Cuartos Fríos / Almacenes (Cold Rooms / Warehouses)
CREATE TABLE IF NOT EXISTS public.warehouses (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL,
    code VARCHAR(50) NOT NULL,
    name VARCHAR(150) NOT NULL,
    type VARCHAR(30) NOT NULL CHECK (type IN ('CHILLER', 'FREEZER', 'DRY', 'PROCESSING')),
    temperature_min NUMERIC(5,2) DEFAULT -2.00,
    temperature_max NUMeric(5,2) DEFAULT 4.00,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_warehouse_tenant_code UNIQUE (tenant_id, code)
);

-- 2. Ubicaciones (Zonas, Racks, Niveles, Posiciones)
CREATE TABLE IF NOT EXISTS public.warehouse_locations (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL,
    warehouse_id UUID NOT NULL REFERENCES public.warehouses(id) ON DELETE CASCADE,
    zone VARCHAR(50) NOT NULL,
    rack VARCHAR(50) NOT NULL,
