    CONSTRAINT fk_warehouse FOREIGN KEY (warehouse_id) REFERENCES public.warehouses(id),
    CONSTRAINT uq_location_barcode UNIQUE (tenant_id, barcode)
);

-- 3. Lotes y Trazabilidad FEFO (First Expire, First Out)
CREATE TABLE IF NOT EXISTS public.inventory_lots (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL,
    product_id UUID NOT NULL,
    lot_number VARCHAR(100) NOT NULL,
    supplier_id UUID,
    received_date TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expiration_date TIMESTAMPTZ NOT NULL,
    initial_quantity NUMERIC(12,4) NOT NULL,
    current_quantity NUMERIC(12,4) NOT NULL,
    unit_cost NUMERIC(14,4) NOT NULL,
    status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'QUARANTINE', 'DEPLETED', 'EXPIRED')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_tenant_lot UNIQUE (tenant_id, product_id, lot_number)
