    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL,
    location_id UUID NOT NULL REFERENCES public.warehouse_locations(id) ON DELETE CASCADE,
    lot_id UUID NOT NULL REFERENCES public.inventory_lots(id) ON DELETE CASCADE,
    quantity NUMERIC(12,4) NOT NULL DEFAULT 0.0000,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_location_lot UNIQUE (tenant_id, location_id, lot_id)
);

-- 5. Movimientos de Inventario WMS (Auditoría y Trazabilidad)
CREATE TABLE IF NOT EXISTS public.inventory_movements (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL,
    movement_type VARCHAR(30) NOT NULL CHECK (movement_type IN ('RECEIVING', 'PUTAWAY', 'PICKING', 'TRANSFER', 'ADJUSTMENT', 'CYCLE_COUNT')),
    lot_id UUID NOT NULL REFERENCES public.inventory_lots(id),
    source_location_id UUID REFERENCES public.warehouse_locations(id),
    target_location_id UUID REFERENCES public.warehouse_locations(id),
    quantity NUMERIC(12,4) NOT NULL,
    reference_document VARCHAR(100),
    performed_by UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
