#### 1.2. Índices de Alto Rendimiento (B-tree y GIN)

```sql
-- Índices B-tree optimizados para búsquedas FEFO y filtros por Tenant
CREATE INDEX IF NOT EXISTS idx_inventory_lots_fefo 
ON public.inventory_lots(tenant_id, product_id, expiration_date) 
WHERE status = 'ACTIVE' AND current_quantity > 0;

CREATE INDEX IF NOT EXISTS idx_location_inventory_tenant 
ON public.location_inventory(tenant_id, location_id);

CREATE INDEX IF NOT EXISTS idx_inventory_movements_tenant_date 
ON public.inventory_movements(tenant_id, created_at DESC);

-- Índice GIN para búsquedas de texto en auditorías y metadatos
CREATE INDEX IF NOT EXISTS idx_inventory_movements_meta_gin 
ON public.inventory_movements USING gin (
    to_tsvector('spanish', coalesce(movement_type, '') || ' ' || coalesce(reference_document, ''))
);
```

