#### 1.4. Función RPC Transaccional con Bloqueo Pesimista (`SELECT FOR UPDATE`)

```sql
CREATE OR REPLACE FUNCTION public.rpc_execute_wms_movement(
    p_tenant_id UUID,
    p_movement_type VARCHAR,
    p_lot_id UUID,
    p_source_location_id UUID,
    p_target_location_id UUID,
    p_quantity NUMERIC,
    p_reference_document VARCHAR,
    p_user_id UUID
) RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_movement_id UUID;
    v_current_lot_qty NUMERIC;
    v_source_qty NUMERIC;
BEGIN
    -- 1. Validación estricta de Tenant Context
    IF p_tenant_id IS NULL OR p_tenant_id::text != nullif(current_setting('request.jwt.claim.app_metadata', true)::json->>'tenant_id', '') THEN
        RAISE EXCEPTION 'Acceso denegado: Violación de contexto Multi-Tenant';
    END IF;

    -- 2. Bloqueo pesimista del lote
    SELECT current_quantity INTO v_current_lot_qty
    FROM public.inventory_lots
    WHERE id = p_lot_id AND tenant_id = p_tenant_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Lote no encontrado o inaccesible.';
    END IF;

    -- 3. Validar si es salida o transferencia (requiere origen)
    IF p_source_location_id IS NOT NULL THEN
        SELECT quantity INTO v_source_qty
        FROM public.location_inventory
        WHERE location_id = p_source_location_id AND lot_id = p_lot_id AND tenant_id = p_tenant_id
        FOR UPDATE;

        IF NOT FOUND OR v_source_qty < p_quantity THEN
            RAISE EXCEPTION 'Stock insuficiente en la ubicación de origen especificada.';
        END IF;

        -- Actualizar origen decreciendo
        UPDATE public.location_inventory
        SET quantity = quantity - p_quantity, updated_at = NOW()
        WHERE location_id = p_source_location_id AND lot_id = p_lot_id;
    END IF;

    -- 4. Validar si es entrada o transferencia (requiere destino)
    IF p_target_location_id IS NOT NULL THEN
        -- Insertar o actualizar destino
        INSERT INTO public.location_inventory (tenant_id, location_id, lot_id, quantity)
        VALUES (p_tenant_id, p_target_location_id, p_lot_id, p_quantity)
        ON CONFLICT (tenant_id, location_id, lot_id)
        DO UPDATE SET quantity = public.location_inventory.quantity + p_quantity, updated_at = NOW();
    END IF;

    -- 5. Actualizar cantidad total del lote si aplica salida neta
    IF p_movement_type IN ('PICKING', 'ADJUSTMENT') AND p_target_location_id IS NULL THEN
        UPDATE public.inventory_lots
        SET current_quantity = current_quantity - p_quantity,
            status = CASE WHEN (current_quantity - p_quantity) <= 0 THEN 'DEPLETED' ELSE status END,
            updated_at = NOW()
        WHERE id = p_lot_id;
    END IF;

    -- 6. Registrar el movimiento en la bitácora
    INSERT INTO public.inventory_movements (
        tenant_id, movement_type, lot_id, source_location_id, target_location_id, quantity, reference_document, performed_by
    ) VALUES (
        p_tenant_id, p_movement_type, p_lot_id, p_source_location_id, p_target_location_id, p_quantity, p_reference_document, p_user_id
    ) RETURNING id INTO v_movement_id;

    RETURN v_movement_id;
END;
$$;
```

