#### 2.1. `useWarehouseStore.ts`

```typescript
import { create } from 'zustand';
import { supabase } from '@/lib/supabaseClient';

export interface Warehouse {
  id: string;
  tenant_id: string;
  code: string;
  name: string;
  type: 'CHILLER' | 'FREEZER' | 'DRY' | 'PROCESSING';
  temperature_min: number;
  temperature_max: number;
  is_active: boolean;
}

export interface WarehouseLocation {
  id: string;
  tenant_id: string;
  warehouse_id: string;
  zone: string;
  rack: string;
  shelf: string;
  position: string;
  barcode: string;
  is_blocked: boolean;
}

interface WarehouseState {
  warehouses: Warehouse[];
  locations: WarehouseLocation[];
  loading: boolean;
  error: string | null;
  fetchWarehouses: () => Promise<void>;
  fetchLocations: (warehouseId?: string) => Promise<void>;
  createWarehouse: (warehouse: Omit<Warehouse, 'id' | 'tenant_id'>) => Promise<void>;
}

export const useWarehouseStore = create<WarehouseState>((set, get) => ({
  warehouses: [],
  locations: [],
  loading: false,
  error: null,

  fetchWarehouses: async () => {
    set({ loading: true, error: null });
    const { data, error } = await supabase
      .from('warehouses')
      .select('*')
      .order('code', { ascending: true });

    if (error) {
      set({ error: error.message, loading: false });
    } else {
      set({ warehouses: data as Warehouse[], loading: false });
    }
  },

  fetchLocations: async (warehouseId?: string) => {
    set({ loading: true, error: null });
    let query = supabase.from('warehouse_locations').select('*');
    if (warehouseId) {
      query = query.eq('warehouse_id', warehouseId);
    }
    const { data, error } = await query;

    if (error) {
      set({ error: error.message, loading: false });
    } else {
      set({ locations: data as WarehouseLocation[], loading: false });
    }
  },

  createWarehouse: async (newWarehouse) => {
    set({ loading: true, error: null });
    const { error } = await supabase.from('warehouses').insert([newWarehouse]);
    if (error) {
      set({ error: error.message, loading: false });
    } else {
      await get().fetchWarehouses();
    }
  },
}));
```

#### 2.2. `useInventoryStore.ts` (Lotes FEFO)

```typescript
import { create } from 'zustand';
import { supabase } from '@/lib/supabaseClient';

export interface InventoryLot {
  id: string;
  tenant_id: string;
  product_id: string;
  lot_number: string;
  supplier_id: string | null;
  received_date: string;
  expiration_date: string;
  initial_quantity: number;
  current_quantity: number;
  unit_cost: number;
  status: 'ACTIVE' | 'QUARANTINE' | 'DEPLETED' | 'EXPIRED';
}

interface InventoryState {
  lots: InventoryLot[];
  loading: boolean;
  error: string | null;
  fetchLotsByProduct: (productId: string) => Promise<void>;
  fetchFefoRecommendation: (productId: string) => Promise<InventoryLot | null>;
}

export const useInventoryStore = create<InventoryState>((set, get) => ({
  lots: [],
  loading: false,
  error: null,

  fetchLotsByProduct: async (productId: string) => {
    set({ loading: true, error: null });
    const { data, error } = await supabase
      .from('inventory_lots')
      .select('*')
      .eq('product_id', productId)
      .eq('status', 'ACTIVE')
      .order('expiration_date', { ascending: true }); // Ordenamiento FEFO natural

    if (error) {
      set({ error: error.message, loading: false });
    } else {
      set({ lots: data as InventoryLot[], loading: false });
    }
  },

  fetchFefoRecommendation: async (productId: string): Promise<InventoryLot | null> => {
    await get().fetchLotsByProduct(productId);
    const activeLots = get().lots;
    return activeLots.length > 0 ? activeLots[0] : null;
  },
}));
```

