import { create } from 'zustand';
import { supabase } from '@/lib/supabaseClient';

export interface WMSMovementPayload {
  tenant_id: string;
  movement_type: 'RECEIVING' | 'PUTAWAY' | 'PICKING' | 'TRANSFER' | 'ADJUSTMENT' | 'CYCLE_COUNT';
  lot_id: string;
  source_location_id: string | null;
