  reference_document: string;
  performed_by: string;
}

interface MovementState {
  loading: boolean;
  error: string | null;
  executeMovement: (payload: WMSMovementPayload) => Promise<boolean>;
}

export const useMovementStore = create<MovementState>((set) => ({
  loading: false,
  error: null,

  executeMovement: async (payload: WMSMovementPayload): Promise<boolean> => {
    set({ loading: true, error: null });
    const { data, error } = await supabase.rpc('rpc_execute_wms_movement', {
      p_tenant_id: payload.tenant_id,
      p_movement_type: payload.movement_type,
      p_lot_id: payload.lot_id,
      p_source_location_id: payload.source_location_id,
      p_target_location_id: payload.target_location_id,
      p_quantity: payload.quantity,
      p_reference_document: payload.reference_document,
      p_user_id: payload.performed_by,
    });

    if (error) {
      set({ error: error.message, loading: false });
      return false;
    }

    set({ loading: false });
    return true;
  },
}));
