import React, { useEffect, useState } from 'react';
import { useInventoryStore, InventoryLot } from '@/store/useInventoryStore';
import { useMovementStore } from '@/store/useMovementStore';
import { ShieldCheck, AlertCircle, ArrowRight } from 'lucide-react';

interface FefoModalProps {
  productId: string;
  requiredQuantity: number;
  tenantId: string;
  userId: string;
  onClose: () => void;
  onSuccess: () => void;
}

export const FefoAllocationModal: React.FC<FefoModalProps> = ({
  productId,
  requiredQuantity,
  tenantId,
  userId,
  onClose,
  onSuccess,
}) => {
  const { lots, fetchLotsByProduct, loading } = useInventoryStore();
  const { executeMovement } = useMovementStore();
  const [selectedLot, setSelectedLot] = useState<InventoryLot | null>(null);

  useEffect(() => {
    fetchLotsByProduct(productId).then(() => {
      // Auto-seleccionar el primer lote FEFO disponible
      const activeLots = useInventoryStore.getState().lots;
      if (activeLots.length > 0) setSelectedLot(activeLots[0]);
    });
  }, [productId, fetchLotsByProduct]);

  const handleConfirmPicking = async () => {
    if (!selectedLot) return;

    const success = await executeMovement({
      tenant_id: tenantId,
      movement_type: 'PICKING',
      lot_id: selectedLot.id,
      source_location_id: null, // Opcional: enlazar con ubicación específica si aplica
      target_location_id: null,
      quantity: requiredQuantity,
      reference_document: 'PICKING-ORDER-FEFO',
      performed_by: userId,
    });

    if (success) {
      onSuccess();
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center p-4 z-50">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-xl p-6 shadow-2xl text-slate-100">
