            <h2 className="text-xl font-bold flex items-center gap-2">
              <ShieldCheck className="text-cyan-400 w-6 h-6" />
              Asignación Automática FEFO
            </h2>
            <p className="text-xs text-slate-400 mt-1">Selección estricta basada en fecha de caducidad más próxima</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white font-mono text-sm">✕</button>
        </div>

        {loading ? (
          <div className="py-8 text-center text-slate-400">Analizando lotes disponibles...</div>
        ) : lots.length === 0 ? (
          <div className="py-8 text-center text-red-400 flex flex-col items-center gap-2">
            <AlertCircle className="w-8 h-8" />
            <span>No hay lotes activos disponibles para este producto.</span>
