            <div className="bg-cyan-950/30 border border-cyan-500/30 rounded-xl p-4">
              <span className="text-xs font-semibold text-cyan-400 uppercase tracking-wider">Lote Sugerido (FEFO)</span>
              {selectedLot && (
                <div className="mt-2 flex justify-between items-center">
                  <div>
                    <p className="text-lg font-bold font-mono">{selectedLot.lot_number}</p>
                    <p className="text-xs text-slate-400">Caducidad: {new Date(selectedLot.expiration_date).toLocaleDateString()}</p>
