                  </div>
                </div>
              )}
            </div>

            <div className="space-y-2">
              <label className="text-xs font-semibold text-slate-400">Otros Lotes en Inventario</label>
              <div className="max-h-48 overflow-y-auto space-y-2 pr-1">
                {lots.map((lot) => (
                  <div 
                    key={lot.id}
