                  >
                    <div>
                      <span className="font-mono font-semibold text-slate-200">{lot.lot_number}</span>
                      <p className="text-xs">Cad: {new Date(lot.expiration_date).toLocaleDateString()}</p>
                    </div>
                    <span className="font-mono text-sm">{lot.current_quantity} un.</span>
                  </div>
                ))}
              </div>
            </div>

            <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-800">
              <button 
                onClick={onClose}
                className="px-4 py-2 rounded-xl bg-slate-800 text-slate-300 hover:bg-slate-700 text-sm font-medium transition-all"
              >
                Cancelar
              </button>
              <button 
                onClick={handleConfirmPicking}
                disabled={!selectedLot || selectedLot.current_quantity < requiredQuantity}
                className="px-5 py-2 rounded-xl bg-cyan-600 text-white hover:bg-cyan-500 text-sm font-semibold transition-all flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Confirmar Picking <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
